<?php require 'admin_guard.php';require 'admin_db.php';$id=$_GET['repoID']??$_POST['repoID'];$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']);$cc=trim($_POST['coursecode']);$s=mysqli_prepare($conn,'UPDATE repository SET name=?,coursecode=? WHERE repoID=?');mysqli_stmt_bind_param($s,'sss',$name,$cc,$id);$msg=mysqli_stmt_execute($s)?'Repository updated successfully.':'Update failed.';}$s=mysqli_prepare($conn,'SELECT * FROM repository WHERE repoID=?');mysqli_stmt_bind_param($s,'s',$id);mysqli_stmt_execute($s);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($s));if(!$r)die('Repository not found');?><!doctype html><html><head><title>Update Repository</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="panel"><h1>Update Repository</h1><?php if($msg)echo'<div class="notice">'.$msg.'</div>';?><form method="post"><input type="hidden" name="repoID" value="<?=$id?>"><label>Course Code</label><input name="coursecode" value="<?=$r['coursecode']?>" required><label>Repository Name</label><input name="name" value="<?=htmlspecialchars($r['name'])?>" required><button>Update</button></form></div></div></body></html>
